export function createTraffic(scene,rnd){const cars=[],people=[];for(let i=0;i<16;i++){let ring=i%3*60;let route=[[-116+ring,-124+ring],[-116+ring,116-ring],[124-ring,116-ring],[124-ring,-124+ring]];let c=createCar(scene,...route[i%4],['#dd9b56','#73aaa5','#c7c8bd','#b86a70'][i%4]);c.route=route;c.target=(i%4+1)%4;cars.push(c)}for(let i=0;i<42;i++){let x=i<12?151:-132+Math.floor(rnd()*5)*60;let z=-145+rnd()*290;let p=createPerson(scene,x,z,['#d9af75','#c77573','#698da8'][i%3]);p.home=x;p.dir=rnd()>.5?1:-1;p.fear=0;people.push(p)}return{cars,people}}
export function updateTraffic(t,dt,state){for(let c of t.cars){if(c===state.car||c.disabled>0){c.disabled=Math.max(0,c.disabled-dt);continue}let target=c.route[c.target],dx=target[0]-c.x,dz=target[1]-c.z,n=Math.hypot(dx,dz);if(n<2){c.target=(c.target+1)%4;continue}c.speed=10;c.angle=Math.atan2(dx,dz);c.x+=dx/n*10*dt;c.z+=dz/n*10*dt;syncCar(c)}for(let p of t.people){let dx=p.x-state.player.x,dz=p.z-state.player.z,n=Math.hypot(dx,dz);if((state.car&&n<15)||state.gunFear>0)p.fear=4;if(p.fear>0){p.fear-=dt;p.x+=dx/(n||1)*dt*6;p.z+=dz/(n||1)*dt*6}else{p.x+=(p.home-p.x)*dt;p.z+=p.dir*dt*1.2}if(Math.abs(p.z)>150){p.dir*=-1;p.z=Math.sign(p.z)*149}p.x=Math.max(-150,Math.min(175,p.x));p.mesh.position.set(p.x,0,p.z);p.mesh.rotation.y=p.fear?Math.atan2(dx,dz):(p.dir>0?0:Math.PI);if(state.car&&n<2&&Math.abs(state.car.speed)>7&&p.hitCooldown<=0){state.crime(1,'Pedestrian collision');p.fear=6;p.hitCooldown=4;p.z+=5;state.health-=5}p.hitCooldown=Math.max(0,(p.hitCooldown||0)-dt)}}
